SELECT , ( SELECT COUNT(*) FROM tb_waybill w WHERE w.courier_code = c.courier_code AND w.waybill_status = 'ISSUED' ) AS waybill_count FROM tb_courier c
ORDER BY ${sortColumn} ${sortDirection}, c.courier_code
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM tb_courier
 WHERE courier_name = #{courierName}

    AND courier_seq <> #{exceptSeq}

SELECT COUNT(*) FROM tb_waybill
 WHERE courier_code   = #{courierCode}
   AND waybill_status = 'ISSUED'

